// Настройка компонента до Play
void Configure(GameComponent& object) {
  object.SetPhysicsEnabled(true);
  object.SetPhysicsBodyType(
      PhysicsBodyType::Dynamic);
  object.SetPhysicsShapeType(
      PhysicsShapeType::Box);
  object.SetPhysicsDensity(1000.0f);
}

// Когда тело уже создано в Play
void Push(GameComponent& object) {
  if (object.HasPhysicsBody())
    object.AddPhysicsImpulse({0, 100, 0});
}
